INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (6, 'ORD202609107f9bea02', 18, 22, 2, 2, '神经内科', '常规全血细胞分析 (血常规)', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 30, '刘主管 (省立二院·检验科) (省立中心医院)', '未见明显异常', '血液细胞分析未见明显病理异常。', '2026-09-10 20:47:16.531000', '1.png', '.png', 'Qmbb5c8256297210c5b91c78a663378270c64f0f5aad696adceba1f17ee0452d69', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-10 20:16:37.574000', '2026-09-10 20:47:16.544000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (7, 'ORD20260910b3e86d03', 18, 22, 2, 2, '神经内科', '血清心肌酶谱与肌钙蛋白', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 30, '刘主管 (省立二院·检验科) (省立中心医院)', '【血常规分析】白细胞 6.5×10^9/L (正常)，中性粒细胞 63%，血红蛋白 138 g/L，血小板 215×10^9/L。', '血液细胞形态及各项数值在正常生理参考区间。', '2026-09-10 20:41:41.290000', '', '', '', '', '2026-09-10 20:16:37.579000', '2026-09-10 20:41:41.290000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (8, 'ORD202609126d4c4a01', 20, 23, 3, 3, '心血管内科', '血清心肌酶谱与肌钙蛋白', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 32, '孙主管 (协和三院·检验科) (协和医学中心)', '【心肌损伤标志物】高敏肌钙蛋白I (hs-cTnI) < 0.01 ng/mL (阴性)，肌酸激酶同工酶 (CK-MB) 1.2 ng/mL (正常)。', '心肌坏死损伤标志物阴性，排除急性心肌梗死。', '2026-09-12 14:58:30.792000', '1.png', '.png', 'Qme9850ff8881922cbb00c54410ebccabf12f77f3eff5b9fc15bb2663a347543b1', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-12 14:53:39.380000', '2026-09-12 14:58:30.800000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (9, 'ORD20260912b2202f02', 20, 23, 3, 3, '心血管内科', '肝肾功能与电解质生化检查', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 32, '孙主管 (协和三院·检验科) (协和医学中心)', '【肝肾功能与电解质生化检查】各项测量参数均在国家标准生理参考区间内，生化代谢指标正常。', '辅助检查指标正常。', '2026-09-12 14:58:05.011000', '1.png', '.png', 'Qm225b4e39670f1a1eb837c965ba79b8b1ffd39e94821f00efc73d5d1a9caed7bb', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-12 14:53:39.384000', '2026-09-12 14:58:05.018000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (10, 'ORD20260912fca87f01', 21, 21, 1, 1, '消化内科', '12导联心电图 (ECG)', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 29, '王医生 (第一医院·影像中心) (第一人民医院)', '【标准12导联静息心电图】\r\n- 节律: 窦性心律，心率 72 bpm\r\n- P波: 时限 0.08s，振幅正常\r\n- P-R间期: 0.16s (参考: 0.12-0.20s)\r\n- QRS波群: 时限 0.09s，各导联形态正常，电轴无显著偏移\r\n- ST-T段: ST段未见明显抬高或压低，T波形态自然直立，Q-Tc间期 412 ms', '窦性心律，大致正常心电图。', '2026-09-12 16:00:48.783000', '', '', '', '', '2026-09-12 16:00:25.667000', '2026-09-12 16:00:48.783000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (11, 'ORD20260912a7b4d002', 21, 21, 1, 1, '消化内科', '胸部高分辨率 CT 平扫', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 29, '王医生 (第一医院·影像中心) (第一人民医院)', '【高分辨率CT平扫检查】\r\n- 双侧胸廓对称，气管通畅。\r\n- 双侧下肺野背段及外底段见散在斑片状、磨玻璃样浅淡高密度影，边界欠清，内可见支气管充气征。\r\n- 纵隔淋巴结轻度反应性肿大，心影大小形态正常，未见明显胸腔积液。', '双下肺野斑片状渗出性病变，考虑感染性病变（社区获得性肺炎表现可能），建议抗炎对症治疗后复查。', '2026-09-12 16:00:44.476000', '', '', '', '', '2026-09-12 16:00:25.674000', '2026-09-12 16:00:44.477000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (12, 'ORD202609122d4b1801', 22, 4, 1, 1, '全科综合门诊', '12导联心电图 (ECG)', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 29, '王医生 (第一医院·影像中心) (第一人民医院)', '【标准12导联静息心电图】\r\n- 节律: 窦性心律，心率 88 bpm\r\n- ST-T段: V4-V6 导联及 II、III、aVF 导联 ST 段呈水平型下移约 0.08-0.12 mV，T波低平伴倒置\r\n- Q-Tc间期: 442 ms', '窦性心律伴下侧壁 ST-T 段缺血性改变，高度提示心肌供血不足，建议结合心肌损伤标志物随诊。', '2026-09-12 16:02:27.149000', '1.png', 'png', 'Qm4b77f3403ac8f10b5ff94da059b998d89888f5fead77ae6b7f5a6be276fcb17b', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-12 16:02:08.471000', '2026-09-12 16:02:27.162000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (13, 'ORD20260912e6addc02', 22, 4, 1, 1, '全科综合门诊', '胸部高分辨率 CT 平扫', '排查急性心肌缺血病变及炎性反应', 'COMPLETED', 29, '王医生 (第一医院·影像中心) (第一人民医院)', '【高分辨率CT平扫检查】\r\n- 右肺中叶外侧段近胸膜下见一结节状磨玻璃密度影，大小约为 8.5 mm × 7.2 mm，边界较清，内部密度欠均，边缘见微小分叶及轻度胸膜牵拉。\r\n- 其余肺野未见明显实变灶，纵隔结构清晰。', '右肺中叶局灶性磨玻璃结节 (pGGN)，建议3个月后薄层低剂量CT随访或呼吸胸外科专科会诊评估。', '2026-09-12 16:02:21.142000', '1.png', 'png', 'Qm553d4fe6fb1674e9a40906388705ae1c388b50d4d20cab4f8ab3ce211dfe96b5', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-12 16:02:08.476000', '2026-09-12 16:02:21.172000');
INSERT INTO `medical_exam_orders` (`id`, `order_no`, `record_id`, `patient_id`, `doctor_id`, `hospital_id`, `department_name`, `exam_item`, `exam_reason`, `status`, `technician_id`, `technician_name`, `exam_result`, `exam_conclusion`, `executed_at`, `report_file_name`, `report_file_type`, `ip_fsc_id`, `file_hash`, `created_at`, `updated_at`) VALUES (14, 'ORD20260913954b3401', 23, 25, 2, 2, '急诊重症科', '常规全血细胞分析 (血常规)', '', 'COMPLETED', 30, '刘主管 (省立二院·检验科) (省立中心医院)', '【全血细胞分析与分类】\r\n- 白细胞计数(WBC): 14.2 ×10^9/L ↑ (参考: 3.5-9.5)\r\n- 中性粒细胞百分比(NEU%): 84.6% ↑ (参考: 40-75)\r\n- 中性粒细胞绝对值(NEU#): 12.0 ×10^9/L ↑\r\n- 超敏C反应蛋白(hs-CRP): 34.5 mg/L ↑ (参考: 0-5)\r\n- 红细胞及血小板未见明显异常', '白细胞总数及中性粒细胞比例显著增高，CRP明显升高，符合急性细菌性感染或活动性炎性反应。', '2026-09-13 10:04:43.833000', '【常规全血细胞分析 (血常规)】报告扫描件.png', 'png', 'Qm651fb0bdeadf7d2f7982fb2c61896a9aba40e0c71f2f08f27f152f973499cd98', 'dd3f657a242d9b1634a58e116fb7ad48543277d8ff404e37f6ce08b44addf0ab', '2026-09-13 10:03:11.695000', '2026-09-13 10:04:43.868000');
