INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (1, 'REC202609001', 4, 1, 1, 'EMR', '2026-09-01 08:30', '持续3天，劳累后加重', '胸骨后压榨样闷痛、伴心悸气促，夜间偶有阵发性呼吸困难', '连续夜班过度劳累诱发；既往高血压病史8年未规律服药；明确慢性乙型病毒性肝炎(HBV)大三阳病毒携带10年(HBsAg阳性)，锐器操作需严密防范刺伤；对青霉素、头孢类抗生素有明确严重过敏史', '1. 完善12导联心电图与心肌酶谱复查；2. 硝苯地平缓释片30mg qd降压；3. 严禁使用β-内酰胺类药物；4. 医护人员严格落实防刺伤职业暴露防护规程', '体温: 36.6℃ | 血压: 155/98 mmHg | 心率: 88 bpm | 血氧: 98%', '【主诉】患者因“胸骨后闷痛3天加重半天”就诊。\n【现病史与诱因】于2026-09-01 08:30发病，劳累诱发，持续3天。\n【既往传染病史】慢性乙型病毒性肝炎 (HBV) 大三阳终身/慢性病毒携带 (HBsAg阳性)，存在血源性职业暴露风险！\n【初步诊断】高血压病II级（中危）；心绞痛待查；慢性乙型病毒性肝炎携带；严重过敏体质。\n【处置建议】降压治疗、心电监护，抽血穿刺必须佩戴双层手套，禁用青霉素头孢。', '74d9f2666f59099b3217b8d48c7c137308356800c4499c873541b89e76bfdb4d', 479, '2026-09-01 10:30:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', '', '', '', '', 0, '', '', '', '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (2, 'REC202609002', 4, 1, 1, 'REPORT', '2026-09-05 13:00', '发作性胸痛2小时', '心前区刺痛，活动后明显，休息后稍缓解', '情绪激动后诱发，高脂饮食史', '1. 急查血常规、生化五项、心肌肌钙蛋白cTnI；2. 口服阿司匹林100mg，单硝酸异山梨酯；3. 观察2小时复测心电图', '体温: 36.7℃ | 血压: 142/90 mmHg | 心率: 92 bpm | 血氧: 99%', '【检查报告小结】血常规生化五项与心肌酶谱检验单：心肌肌钙蛋白与CK-MB处于边缘正常上限，建议结合临床症状动态复查以排除ACS。', 'c117a92519e76aabc46daa72cc0f8f74bdc432db8869a63b793933bd9bb381bf', 480, '2026-09-05 14:15:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (3, 'REC20260910351c4d04', 4, 2, 2, 'EMR', '2026-08-15 22:40', '突发撕裂样胸痛伴大汗1小时', '胸骨后及后背撕裂样剧烈疼痛，大汗淋漓，濒死感明显，肢端湿冷', '重度高血压长期未规范用药，重体力搬运后诱发；对青霉素类药物严重过敏史', '1. 绝对卧床制动、心电监护与高流量吸氧；2. 硝普钠微泵严密控压；3. 急诊胸痛介入抢救中心会诊，排除急性主动脉夹层', '体温: 36.4℃ | 血压: 85/50 mmHg | 心率: 115 bpm | 血氧: 91%', '【省立中心医院·急诊抢救病历】急性心肌梗死待排；主动脉夹层待排；心源性休克前兆。需跨院紧急调阅既往心血管造影及严重药物过敏史！', '5efd1dfc53b8d36166f1fb37d18275aab2b9aa8187a4e2b90fdc40deadd679fa', 481, '2026-09-10 15:52:59.812000', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (4, 'REC20260720C01', 4, 3, 3, 'REPORT', '2026-07-20 09:15', '间歇性头晕视物旋转1周', '头部位置变动时眩晕加重，伴耳鸣及恶心感，无面瘫与肢体运动障碍', '颈椎退行性病变压迫椎基底动脉，近期连续熬夜失眠诱发', '1. 颈椎平扫MRI与经颅多普勒(TCD)检查；2. 口服甲磺酸倍他司汀片抗眩晕；3. 避免长时间低头伏案', '体温: 36.5℃ | 血压: 130/85 mmHg | 心率: 74 bpm | 血氧: 99%', '【协和医学中心·神经内科报告】颈椎退行性改变伴椎-基底动脉供血不足；TCD提示右侧椎动脉血流流速减缓。', '2b9a1b3d5724240cf3c7b4bc12b319d382487904f6ed2aed20112a39d3f5c218', 482, '2026-07-20 10:30:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (5, 'REC20260902A01', 5, 1, 1, 'EMR', '2026-09-02 14:20', '劳累后胸闷胸痛1个月，加重3天', '快步行走或爬楼至3层出现心前区憋闷压榨感，持续约3-5分钟，含服硝酸甘油可缓解', '吸烟史15年，高脂血症病史5年；无明确药物过敏史', '1. 口服阿司匹林肠溶片 100mg qd 抗血小板；2. 阿托伐他汀钙片 20mg qn 降脂稳斑；3. 择期行冠脉CTA造影明确狭窄程度', '体温: 36.8℃ | 血压: 138/88 mmHg | 心率: 76 bpm | 血氧: 98%', '【第一医院心内科】冠状动脉粥样硬化性心脏病；稳定型心绞痛；高脂血症。建议避免重体力负荷并门诊复查。', '66c5ac2f0721b46e3c26c0d7676cbe561cdac086944e00f9be642cf9bc3b1404', 483, '2026-09-02 15:00:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
