INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (7, 'REC20260828A01', 20, 1, 1, 'REPORT', '2026-08-28 09:30', '高血压病慢性随访半年，偶有头昏', '晨起轻微头胀，休息后缓解，无肢体无力及视物成双', '老年性动脉硬化伴糖尿病血管病变，日常低盐饮食执行不佳', '1. 缬沙坦胶囊 80mg qd；2. 监测晨起及睡前双重血压；3. 保持与协和内分泌科降糖方案协同治疗', '体温: 36.6℃ | 血压: 150/92 mmHg | 心率: 72 bpm | 血氧: 99%', '【第一医院门诊随诊】原发性高血压II级很高危组；糖尿病合并动脉粥样硬化。已与协和医院建立跨院互通档案。', '2edb7194637cc5e4229ea7b7bd9267d9944a9c0a923e1c0607a130a9cb8a8f4d', 485, '2026-08-28 10:15:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (8, 'REC20260906A02', 21, 8, 1, 'EMR', '2026-09-06 15:30', '反复腰痛伴左下肢放射痛半年，加重1周', '腰背部酸痛，久坐久站加剧，放射至左小腿后外侧及足背，左足大拇趾背伸肌力IV级', '从事重型机械长途驾驶，长年久坐震动劳损；无既往药物食物过敏史', '1. 绝对硬板床休息并佩戴定制腰围；2. 塞来昔布胶囊 0.2g bid 消炎止痛；3. 完善腰椎三维CT重建，评估椎间孔镜微创手术指征', '体温: 36.7℃ | 血压: 125/80 mmHg | 心率: 68 bpm | 血氧: 99%', '【第一医院骨科门诊】腰椎间盘突出症(L4-L5中央偏左型，压迫左侧L5神经根)；腰椎管退行性狭窄。', 'bb3035aa793c35ab1a5375a7de7cc6ae1e6cc6826649a6afca070f6008bd09b9', 486, '2026-09-06 16:40:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (9, 'REC20260830B02', 22, 2, 2, 'EMR', '2026-08-30 02:15', '突发呼吸困难伴严重喘息1小时急救', '端坐呼吸，大汗淋漓，双肺听诊满布广泛高调哮鸣音，呼吸音极弱(寂静肺征象)', '接触猫毛后急性激发，既往严重支气管哮喘病史12年；对阿司匹林及非甾体抗炎药(NSAIDs)有阿司匹林哮喘严重反应史', '1. 高流量面罩吸氧；2. 甲泼尼龙琥珀酸钠 80mg 静脉注射抗炎；3. 硫酸特布他林联合异丙托溴铵雾化吸入；4. 绝对禁用阿司匹林等非甾体类镇痛解热药', '体温: 37.1℃ | 血压: 160/105 mmHg | 心率: 128 bpm | 血氧: 87%', '【省立中心医院急诊抢救】支气管哮喘急性重度发作(危重度)；急性呼吸衰竭代偿期；阿司匹林哮喘三联征。需跨院重点核实既往过敏史！', '85f31a5b35891fd809271bf7337671c3d650cf9077c77a0523d8828d53fa8811', 487, '2026-08-30 03:30:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (10, 'REC20260908C02', 22, 15, 3, 'REPORT', '2026-09-08 11:00', '反复过敏性鼻炎伴咳嗽哮喘半年慢病评估', '阵发性喷嚏、清涕，遇冷空气刺激后刺激性干咳，夜间偶有喉间痰鸣', '特应性过敏体质，血清总IgE高达 1280 IU/mL；吸入物过敏原筛查粉尘螨(++++)', '1. 布地奈德福莫特罗粉吸入剂 160/4.5ug 早晚各一吸；2. 孟鲁司特钠片 10mg qn 抗白三烯；3. 严格环境避螨防尘', '体温: 36.6℃ | 血压: 118/75 mmHg | 心率: 74 bpm | 血氧: 99%', '【协和免疫科报告】特应性支气管哮喘(慢性持续期)；中重度变应性鼻炎。肺功能检查提示中度阻塞性通气功能障碍，支气管舒张试验阳性。', '6bf1d59c16c5ac977fc6f62e68d9c572ff782253a7ec13869b94e74dc143a81c', 488, '2026-09-08 11:45:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (11, 'REC20260901A03', 23, 8, 1, 'IMAGE', '2026-09-01 16:00', '打篮球扭伤右膝关节伴肿胀活动受限半天', '右膝关节弥漫性肿胀，浮髌试验(+)，抽屉试验(+)，不能负重行走', '剧烈对抗运动扭转受伤，既往身体强健，无任何药物过敏史', '1. 急诊右膝冷敷、加压包扎及支具固定；2. 行右膝关节高场强MRI平扫排查韧带撕裂；3. 择期行关节镜下前交叉韧带自体肌腱重建术', '体温: 36.8℃ | 血压: 122/78 mmHg | 心率: 82 bpm | 血氧: 100%', '【第一医院骨科影像】右膝前交叉韧带断裂(全层撕裂伴周围水肿)；内侧半月板后角II-III度撕裂；关节腔中度积血积液。', '382ef5b6211e3123edfe7c84b45cd590908141026426dfe02960b7bff161dee5', 489, '2026-09-01 17:10:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (12, 'REC20260905B03', 24, 9, 1, 'EMR', '2026-09-05 08:30', '慢性咳喘20年，受凉后加重伴气急嗜睡2天', '咳大量黄色黏稠脓痰，不易咳出，呼吸急促费力，口唇发绀，查体剑突下心脏搏动增强', '长期农村土灶柴烟接触史，既往慢性支气管炎肺气肿20年；对头孢菌素类药物有过敏性药疹史', '1. 持续低流量吸氧(1.5 L/min)配合无创双水平正压通气(BiPAP)；2. 莫西沙星氯化钠注射液抗感染；3. 氨茶碱注射液平喘祛痰', '体温: 37.8℃ | 血压: 135/85 mmHg | 心率: 105 bpm | 血氧: 84%', '【第一医院呼吸危重症】慢性阻塞性肺疾病急性加重期(AECOPD)；II型呼吸衰竭；慢性肺源性心脏病(失代偿期)；头孢药物过敏。', '0833bb16aee27cc85aaa2441b35d9025706eeb5973978465d52d6008455c02e0', 490, '2026-09-05 09:40:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (13, 'REC202609103eb470dd', 4, 2, 2, 'REPORT', '2026-09-08 00:00:00', '持续2天，活动后加剧', '患者咳嗽，喉咙痛', '患者感冒，扁桃体发炎', '服用药物，不宜吃辣', '体温: 36.8℃ | 血压: 145/95 mmHg | 脉搏: 95 bpm | 血氧: 98%', '【主诉】患者张三（身份证: 110101********2315，联系电话: 13900000001），因“患者咳嗽，喉咙痛持续持续2天，活动后加剧”来院就诊。\r\n\r\n【现病史与诱发因素】患者于 2026-09-08 00:00:00 起病。起病主要诱因：患者感冒，扁桃体发炎。病程中临床表现主要为：患者咳嗽，喉咙痛，持续时间约 持续2天，活动后加剧。\r\n\r\n【生命体征检测】体温: 36.8℃ | 血压: 145/95 mmHg | 脉搏: 95 bpm | 血氧: 98%\r\n\r\n【临床初步诊断评估】结合病史、诱因及临床表现，拟诊为相关系统病变（分类：RESP），排查急性器质性损伤。\r\n\r\n【解决方案与治疗处方建议】\r\n服用药物，不宜吃辣\r\n\r\n【存证提示】本记录已纳入 MedTrust 区块链跨机构协同网络，由经治医生确认并执行链下加密与分布式凭证固化。', 'a4a53dda6afb1c38cce520d99a22d4fd2007b435e4f6668245ce3964f4a31ca3', 491, '2026-09-10 19:15:54.566000', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (14, 'REC20260810C05', 26, 15, 3, 'EMR', '2026-08-10 10:00', '发热乏力伴体重下降1个月', '发热伴全身多发浅表淋巴结肿大，夜间盗汗，纳差消瘦，易反复口腔真菌感染', '人类免疫缺陷病毒(HIV-1)感染，必定终身携带，免疫功能低下(CD4计数 180 cells/uL)；医护职业暴露极高危(血液体液/针刺伤)', '1. 规范启动国家免费一线免费抗病毒治疗(ART)：替诺福韦+拉米夫定+多替拉韦；2. 口服复方磺胺甲噁唑预防卡氏肺孢子虫肺炎；3. 严格落实医务人员标准预防与双层手套、面屏防溅职业暴露安全防护规程', '体温: 37.6℃ | 血压: 115/75 mmHg | 心率: 86 bpm | 血氧: 98%', '【协和感染科最终确诊】获得性免疫缺陷综合征 (AIDS)；人类免疫缺陷病毒感染 (HIV抗体确证试验阳性，必定终身携带)；口腔念珠菌感染。【医护安全警报】该患者为血源性高危传染病确诊携带者，侵入性操作严防锐器刺伤，穿戴双层手套及防溅面屏！', 'e9ed9a1459d83e380e96af1f0a4adc38f4359b5c9600e0c5b5ccbf9ccf90a823', 139, '2026-08-10 11:30:00', 'OUTPATIENT', '综合门诊', 'COMPLETED', NULL, NULL, NULL, NULL, 0, '', NULL, NULL, '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (15, 'REC20260820A05', 27, 9, 1, 'EMR', '2026-08-20 09:15', '阵发性咳嗽咳痰2个月，咯血3天', '咳嗽、咳大量黄脓痰，午后潮热(T: 38.2℃)，夜间盗汗，近3天出现痰中带鲜血丝，活动后胸闷气促', '结核分枝杆菌耐多药复合株感染，处于活动期持续排菌状态；呼吸道飞沫与气溶胶传播风险极高', '1. 立即收住负压结核呼吸隔离病房，严格实施空气与飞沫隔离；2. 二线耐多药结核方案抗感染：贝达喹啉+利奈唑胺+环丝氨酸；3. 接诊医护人员必须严格佩戴 N95 医用防护口罩与防护面罩', '体温: 38.2℃ | 血压: 122/78 mmHg | 心率: 96 bpm | 血氧: 94%', '【第一医院呼吸科确诊】继发性活动性肺结核 (涂阳排菌型)；耐多药结核 (MDR-TB)；支气管扩张伴小量咯血。【医护安全警报】患者痰抗酸杆菌涂片(+++)，活动期强排菌，空气飞沫高度传染，接诊医护必须严格穿戴N95口罩与医用隔离衣！', '4459cd9815043ce3ff184a8189047e610a1bef2c43af7cc134d37a8dff9252ec', 492, '2026-09-10 19:43:18.397000', 'OUTPATIENT', '心血管内科', 'COMPLETED', '发作性胸骨后压榨性闷痛3天，劳累后加重', '患者3天前爬楼劳累后突感心前区及胸骨后压榨样闷痛，每次持续3-5分钟，伴心悸、冷汗，休息后可自行缓解。', '冠状动脉粥样硬化性心脏病（疑似劳力型心绞痛）', '中年男性，活动诱发胸骨后压榨性闷痛，休息后缓解，既往有轻度高血压史。', 1, '12导联心电图 (ECG), 常规全血细胞分析 (血常规), 血清心肌酶谱与肌钙蛋白', '排查急性冠脉综合征与心肌缺血病变', '【12导联心电图】窦性心律，V4-V6导联ST段轻度压低0.05mV，T波低平。\n【心肌酶谱】cTnI < 0.02 ng/mL (阴性)，排除急性心梗。', '心电图室 孙主治医师', '2026-09-10 10:15:00', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (16, 'ENC20260910fba74b31', 4, 1, 1, 'EMR', '2026-09-10 14:00', '发作2天', '胸闷心悸伴气促2天', '长期劳累及精神紧张导致交感神经兴奋性增高、外周血管阻力增大。', '1. 苯磺酸氨氯地平片 5mg po qd 降压；\n2. 劳逸结合，清淡低盐饮食；\n3. 2周后心内科门诊复查血压。', 'T: 36.5℃, BP: 142/90 mmHg, HR: 96 bpm, SpO2: 97%', '原发性高血压病1级，心肌轻度供血不足', 'b6056d6c2157257623e3c5cd360d47c2ca8af9df57ab1971f247bf00c5c06c18', 493, '2026-09-10 19:57:19.806000', 'OUTPATIENT', '心血管内科', 'COMPLETED', '胸闷心悸伴气促2天', '患者于2天前爬楼梯后突发胸骨后闷痛，伴心慌出汗，休息后轻度缓解。', '冠脉缺血待查，心律失常待排', '中年男性，活动后突发胸骨后闷痛伴心慌，查体血压偏高、心率偏快。', 1, '12导联心电图 (ECG), 常规全血细胞分析 (血常规)', '排查急性心肌缺血与血液炎性反应', '【12导联心电图 (ECG)】针对【12导联心电图 (ECG)】已完成标准检测，各项数值波形处于正常生理范围。\n结论: 未见明显器质性病变 (技师: 检验科李技师, 时间: 2026-09-10 19:57)\n【常规全血细胞分析 (血常规)】针对【常规全血细胞分析 (血常规)】已完成标准检测，各项数值波形处于正常生理范围。\n结论: 未见明显器质性病变 (技师: 检验科李技师, 时间: 2026-09-10 19:57)', '检验科李技师', '2026-09-10 19:57:19', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (17, 'ENC20260910dfcba912', 4, 1, 1, 'EMR', '2026-09-10 15:30:00', '反复发作 3 天', '劳累后胸骨后压榨性闷痛3天，伴出汗心悸', '精神长期紧张及体力劳累诱发交感神经过度兴奋，外周阻力血管收缩。', '1. 苯磺酸氨氯地平片 5mg 口服 每日一次；\n2. 规律监测早晚血压并记录；\n3. 低盐低脂饮食，避免重体力劳动及剧烈情绪波动；\n4. 2周后心内科门诊复查。', 'T: 36.6℃, BP: 145/92 mmHg, HR: 94 bpm, SpO2: 97%', '原发性高血压病1级，轻度心肌供血不足', 'f160f7ef1ceacc9ef060e8cb0c459ec2ccded4529fd687b04b859e04ba82d03c', 494, '2026-09-10 20:00:18.490000', 'OUTPATIENT', '心血管内科', 'COMPLETED', '劳累后胸骨后压榨性闷痛3天，伴出汗心悸', '患者3天前爬楼梯后突发心前区闷痛，每次持续3-5分钟，休息后可轻度缓解。', '原发性高血压病1级待查；冠状动脉粥样硬化性心脏病待排', '中年男性，活动诱发胸痛心悸，查体血压偏高、心率较快。', 1, '12导联心电图 (ECG), 血清心肌酶谱与肌钙蛋白', '排除急性心肌缺血及心肌损伤', '【12导联心电图 (ECG)】【12导联心电图 (ECG)】各导联形态时限无明显病理性偏移，指标处于健康生理参考区间。\n结论: 大致正常，未见明显器质性病理征象 (技师: 李主管技师, 时间: 2026-09-10 20:00)\n【血清心肌酶谱与肌钙蛋白】【血清心肌酶谱与肌钙蛋白】各导联形态时限无明显病理性偏移，指标处于健康生理参考区间。\n结论: 大致正常，未见明显器质性病理征象 (技师: 李主管技师, 时间: 2026-09-10 20:00)', '李主管技师', '2026-09-10 20:00:18', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (18, 'ENC2026091076f68996', 22, 2, 2, 'EMR', '2026-09-09 12:15:44', '头痛2天', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', '1. 苯磺酸氨氯地平片 5mg 口服 每日一次；\\n2. 规律监测晨起及睡前血压；\\n3. 限制钠盐摄入 (每日<5g)，保证充足睡眠；\\n4. 2周后复查血压及心电图。', 'T: 36.6℃, BP: 128/82 mmHg, HR: 76 bpm, SpO2: 98%', '原发性高血压病1级，心肌轻度供血不足', '1e678555d21b487259a8b60465fbf85bda387ad0a1cafb19c48e3a5ac5356b07', 495, '2026-09-10 20:16:37.563000', 'OUTPATIENT', '神经内科', 'COMPLETED', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '患者2天前爬楼劳累后突感心前区及胸骨后压榨样闷痛，每次持续3-5分钟，伴心慌出冷汗，休息后可轻微缓解。', '原发性高血压病1级待查；冠脉缺血待排', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', 1, '12导联心电图 (ECG), 常规全血细胞分析 (血常规), 血清心肌酶谱与肌钙蛋白', '排查急性心肌缺血病变及炎性反应', '【12导联心电图 (ECG)】【12导联心电图】窦性心律，心率 92 bpm，V4-V6 导联 ST 段呈水平型压低约 0.08 mV，T波低平伴轻度倒置。\n结论: 窦性心律伴轻度心肌缺血改变，建议结合临床症状随诊。 ([省立中心医院] 出具人: 刘主管 (省立二院·检验科) (省立中心医院), 时间: 2026-09-10 20:47)\n【常规全血细胞分析 (血常规)】未见明显异常\n结论: 血液细胞分析未见明显病理异常。 ([省立中心医院] 出具人: 刘主管 (省立二院·检验科) (省立中心医院), 时间: 2026-09-10 20:47)\n【血清心肌酶谱与肌钙蛋白】【血常规分析】白细胞 6.5×10^9/L (正常)，中性粒细胞 63%，血红蛋白 138 g/L，血小板 215×10^9/L。\n结论: 血液细胞形态及各项数值在正常生理参考区间。 ([省立中心医院] 出具人: 刘主管 (省立二院·检验科) (省立中心医院), 时间: 2026-09-10 20:41)', '刘主管 (省立二院·检验科) (省立中心医院)', '2026-09-10 20:47:44', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (19, 'ENC20260910a261bbc9', 4, 1, 1, 'EMR', '2026-09-10 16:00:00', '阵发性胸闷 2 天', '反复心前区隐痛不适2天', '劳累致植物神经功能紊乱，外周小动脉阻力增高。', '1. 硝苯地平控释片 30mg 口服 每日一次；2. 低盐低脂饮食；3. 规律作息。', 'T: 36.5℃, BP: 124/82 mmHg, HR: 72 bpm, SpO2: 99%', '原发性高血压病1级（低危组）', 'd7a8dc79f2d752ec65655a2f5ef2f77c207a29645cc3b44403946d2ce0402149', 496, '2026-09-10 21:14:01.140000', 'OUTPATIENT', '心血管内科', 'COMPLETED', '反复心前区隐痛不适2天', '患者2天前劳累后感心前区隐痛，无明显放射痛，休息后自行缓解。', '原发性高血压病1级（低危组）', '临床体征明确，血压轻度增高', 0, '', '', '', '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (20, 'ENC20260912c2babe17', 23, 3, 3, 'EMR', '2026-09-12 06:51:08', '阵发性胸闷 2 天', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', '1. 苯磺酸氨氯地平片 5mg 口服 每日一次；\\n2. 规律监测晨起及睡前血压；\\n3. 限制钠盐摄入 (每日<5g)，保证充足睡眠；\\n4. 2周后复查血压及心电图。', 'T: 36.6℃, BP: 128/82 mmHg, HR: 76 bpm, SpO2: 98%', '原发性高血压病1级，心肌轻度供血不足', 'd2bcf1e027c97da729919065fbf0f4c2261539a710caac762bd61390047cd010', 497, '2026-09-12 14:53:39.374000', 'EMERGENCY', '心血管内科', 'COMPLETED', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '患者2天前爬楼劳累后突感心前区及胸骨后压榨样闷痛，每次持续3-5分钟，伴心慌出冷汗，休息后可轻微缓解。', '原发性高血压病1级待查；冠脉缺血待排', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', 1, '血清心肌酶谱与肌钙蛋白, 肝肾功能与电解质生化检查', '排查急性心肌缺血病变及炎性反应', '【血清心肌酶谱与肌钙蛋白】【心肌损伤标志物】高敏肌钙蛋白I (hs-cTnI) < 0.01 ng/mL (阴性)，肌酸激酶同工酶 (CK-MB) 1.2 ng/mL (正常)。\n结论: 心肌坏死损伤标志物阴性，排除急性心肌梗死。 ([协和医学中心] 出具人: 孙主管 (协和三院·检验科) (协和医学中心), 时间: 2026-09-12 14:58)\n【肝肾功能与电解质生化检查】【肝肾功能与电解质生化检查】各项测量参数均在国家标准生理参考区间内，生化代谢指标正常。\n结论: 辅助检查指标正常。 ([协和医学中心] 出具人: 孙主管 (协和三院·检验科) (协和医学中心), 时间: 2026-09-12 14:58)', '孙主管 (协和三院·检验科) (协和医学中心)', '2026-09-12 14:58:30', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (21, 'ENC20260912faee5cda', 21, 1, 1, 'EMR', '2026-09-12 08:00:06', '阵发性胸闷 2 天', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', '', 'T: 36.6℃, BP: 128/82 mmHg, HR: 76 bpm, SpO2: 98%', '', '2081652296067d7a610bd69e8ef16187893f418733c1cba7dec7242d5afce563', 146, '2026-09-12 16:00:25.653000', 'OUTPATIENT', '消化内科', 'EXAM_COMPLETED', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '患者2天前爬楼劳累后突感心前区及胸骨后压榨样闷痛，每次持续3-5分钟，伴心慌出冷汗，休息后可轻微缓解。', '原发性高血压病1级待查；冠脉缺血待排', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', 1, '12导联心电图 (ECG), 胸部高分辨率 CT 平扫', '排查急性心肌缺血病变及炎性反应', '【12导联心电图 (ECG)】【标准12导联静息心电图】\r\n- 节律: 窦性心律，心率 72 bpm\r\n- P波: 时限 0.08s，振幅正常\r\n- P-R间期: 0.16s (参考: 0.12-0.20s)\r\n- QRS波群: 时限 0.09s，各导联形态正常，电轴无显著偏移\r\n- ST-T段: ST段未见明显抬高或压低，T波形态自然直立，Q-Tc间期 412 ms\n结论: 窦性心律，大致正常心电图。 ([第一人民医院] 出具人: 王医生 (第一医院·影像中心) (第一人民医院), 时间: 2026-09-12 16:00)\n【胸部高分辨率 CT 平扫】【高分辨率CT平扫检查】\r\n- 双侧胸廓对称，气管通畅。\r\n- 双侧下肺野背段及外底段见散在斑片状、磨玻璃样浅淡高密度影，边界欠清，内可见支气管充气征。\r\n- 纵隔淋巴结轻度反应性肿大，心影大小形态正常，未见明显胸腔积液。\n结论: 双下肺野斑片状渗出性病变，考虑感染性病变（社区获得性肺炎表现可能），建议抗炎对症治疗后复查。 ([第一人民医院] 出具人: 王医生 (第一医院·影像中心) (第一人民医院), 时间: 2026-09-12 16:00)', '王医生 (第一医院·影像中心) (第一人民医院)', '2026-09-12 16:00:48', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (22, 'ENC2026091266dc9144', 4, 1, 1, 'EMR', '2026-09-12 08:01:54', '阵发性胸闷 2 天', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', '1. 苯磺酸氨氯地平片 5mg 口服 每日一次；\\n2. 规律监测晨起及睡前血压；\\n3. 限制钠盐摄入 (每日<5g)，保证充足睡眠；\\n4. 2周后复查血压及心电图。', 'T: 36.6℃, BP: 128/82 mmHg, HR: 76 bpm, SpO2: 98%', '原发性高血压病1级，心肌轻度供血不足', 'e16580bf4d92c66cd4245e7aba97fdfc3566287b162e084a1a3e92cce012417a', 498, '2026-09-12 16:02:08.461000', 'OUTPATIENT', '全科综合门诊', 'COMPLETED', '胸骨后发作性压榨样闷痛2天，劳累后加剧', '患者2天前爬楼劳累后突感心前区及胸骨后压榨样闷痛，每次持续3-5分钟，伴心慌出冷汗，休息后可轻微缓解。', '原发性高血压病1级待查；冠脉缺血待排', '中年患者，活动诱发胸闷心悸，既往有轻度血压偏高史，需心电图及血常规排查。', 1, '12导联心电图 (ECG), 胸部高分辨率 CT 平扫', '排查急性心肌缺血病变及炎性反应', '【12导联心电图 (ECG)】【标准12导联静息心电图】\r\n- 节律: 窦性心律，心率 88 bpm\r\n- ST-T段: V4-V6 导联及 II、III、aVF 导联 ST 段呈水平型下移约 0.08-0.12 mV，T波低平伴倒置\r\n- Q-Tc间期: 442 ms\n结论: 窦性心律伴下侧壁 ST-T 段缺血性改变，高度提示心肌供血不足，建议结合心肌损伤标志物随诊。 ([第一人民医院] 出具人: 王医生 (第一医院·影像中心) (第一人民医院), 时间: 2026-09-12 16:02)\n【胸部高分辨率 CT 平扫】【高分辨率CT平扫检查】\r\n- 右肺中叶外侧段近胸膜下见一结节状磨玻璃密度影，大小约为 8.5 mm × 7.2 mm，边界较清，内部密度欠均，边缘见微小分叶及轻度胸膜牵拉。\r\n- 其余肺野未见明显实变灶，纵隔结构清晰。\n结论: 右肺中叶局灶性磨玻璃结节 (pGGN)，建议3个月后薄层低剂量CT随访或呼吸胸外科专科会诊评估。 ([第一人民医院] 出具人: 王医生 (第一医院·影像中心) (第一人民医院), 时间: 2026-09-12 16:02)', '王医生 (第一医院·影像中心) (第一人民医院)', '2026-09-12 16:02:27', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (23, 'ENC20260913c6e40c80', 25, 2, 2, 'EMR', '2026-09-13 02:01:10', '阵发性胸闷 2 天', '咳嗽，发烧2天', '需抽血化验确认', '吃头孢', 'T: 38.1℃, BP: 128/82 mmHg, HR: 76 bpm, SpO2: 98%', '细菌感染', '53ef2267c50c518af74ab6cd5474cf8e5051520d56d00944730908bde2a7aec7', 499, '2026-09-13 10:03:11.684000', 'OUTPATIENT', '急诊重症科', 'COMPLETED', '咳嗽，发烧2天', '患者正常生活', '细菌/病毒感染', '需抽血化验确认', 1, '常规全血细胞分析 (血常规)', '', '【常规全血细胞分析 (血常规)】【全血细胞分析与分类】\r\n- 白细胞计数(WBC): 14.2 ×10^9/L ↑ (参考: 3.5-9.5)\r\n- 中性粒细胞百分比(NEU%): 84.6% ↑ (参考: 40-75)\r\n- 中性粒细胞绝对值(NEU#): 12.0 ×10^9/L ↑\r\n- 超敏C反应蛋白(hs-CRP): 34.5 mg/L ↑ (参考: 0-5)\r\n- 红细胞及血小板未见明显异常\n结论: 白细胞总数及中性粒细胞比例显著增高，CRP明显升高，符合急性细菌性感染或活动性炎性反应。 ([省立中心医院] 出具人: 刘主管 (省立二院·检验科) (省立中心医院), 时间: 2026-09-13 10:04)', '刘主管 (省立二院·检验科) (省立中心医院)', '2026-09-13 10:04:43', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
INSERT INTO `medical_records` (`id`, `record_no`, `patient_id`, `doctor_id`, `hospital_id`, `data_type`, `onset_time`, `duration`, `symptoms`, `etiology`, `treatment_plan`, `vital_signs`, `diagnosis`, `fabric_tx_id`, `block_height`, `created_at`, `encounter_type`, `department_name`, `status`, `chief_complaint`, `present_illness`, `initial_diagnosis`, `diagnostic_basis`, `need_exam`, `exam_items`, `exam_reason`, `exam_result`, `exam_doctor`, `exam_time`, `sync_status`, `idempotency_key`, `sync_error`, `retry_count`, `department_id`, `title`, `integrity_status`) VALUES (24, 'ENC202609138525109c', 4, 1, 1, 'EMR', '2026-09-13 11:20:00', '反复胸闷3天', '劳累后活动性胸闷气促3天，休息可轻微缓解', '劳累诱发血管舒缩神经失调，外周小动脉阻力增高，心肌负荷增大', '【综合处置】\n1. 门诊心电图与生命体征监测，建立外周静脉通路\n2. 低流量鼻导管吸氧 (2-3 L/min)\n\n【临床医嘱】\n1. 饮食指导：严格低盐低脂清淡饮食（每日食盐<5g）\n2. 每日晨起及睡前监测血压并详细做健康日志记录\n3. 2周后心血管内科专科门诊复查心电图\n\n【处方用药】\n1. 硝苯地平控释片 (拜新同) 30mg 口服 每日一次 清晨餐后整片吞服\n2. 阿托伐他汀钙片 (立普妥) 20mg 口服 每晚睡前一次', 'T: 36.6℃, BP: 145/92 mmHg, HR: 82 bpm, SpO2: 98%', '原发性高血压病1级（中危组）', '093906c19889e5abbcf424ae9e0886256312678394b0c00aefce75ef69df2478', 500, '2026-09-13 11:21:22.598000', 'OUTPATIENT', '心血管内科', 'COMPLETED', '劳累后活动性胸闷气促3天，休息可轻微缓解', '患者3天前爬楼劳累后突感心前区压榨闷痛，每次持续3-5分钟，休息后稍缓解。', '原发性高血压病1级（中危）', '既往血压偏高未规律服药，现病史及查体血压145/92mmHg', 0, '', '', '', '', '', 'COMPLETED', NULL, NULL, 0, 0, '', 'VERIFIED');
