-- MedTrust Automated Full Schema & Seed Data Initialization for Docker
CREATE DATABASE IF NOT EXISTS medtrust DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE medtrust;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for access_requests
-- ----------------------------
DROP TABLE IF EXISTS `access_requests`;
CREATE TABLE `access_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `request_no` varchar(64) DEFAULT NULL,
  `doctor_id` bigint unsigned DEFAULT NULL,
  `patient_id` bigint unsigned DEFAULT NULL,
  `record_id` bigint unsigned DEFAULT NULL,
  `source_hospital_id` bigint unsigned DEFAULT NULL,
  `target_hospital_id` bigint unsigned DEFAULT NULL,
  `purpose` varchar(255) DEFAULT NULL,
  `risk_score` bigint DEFAULT '0',
  `risk_level` varchar(20) DEFAULT 'LOW',
  `decision` varchar(20) DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'PENDING',
  `scope_type` varchar(20) DEFAULT 'SINGLE',
  `days` bigint DEFAULT '7',
  `expire_at` datetime(3) DEFAULT NULL,
  `risk_detail` varchar(512) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_access_requests_request_no` (`request_no`),
  KEY `idx_doctor_patient` (`doctor_id`,`patient_id`),
  KEY `idx_access_requests_expire_at` (`expire_at`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of access_requests

-- ----------------------------
-- Table structure for audit_logs
-- ----------------------------
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(64) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `operation_type` varchar(50) DEFAULT NULL,
  `target_type` varchar(50) DEFAULT NULL,
  `target_id` varchar(64) DEFAULT NULL,
  `hospital_id` bigint unsigned DEFAULT NULL,
  `result` varchar(20) DEFAULT NULL,
  `risk_level` varchar(20) DEFAULT 'LOW',
  `ip_address` varchar(50) DEFAULT '',
  `fabric_tx_id` varchar(128) DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  `risk_score` bigint DEFAULT '0',
  `source` varchar(30) DEFAULT 'WEB',
  `reason` varchar(255) DEFAULT '',
  `user_agent` varchar(255) DEFAULT '',
  `detail` varchar(512) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_audit_logs_log_id` (`log_id`),
  KEY `idx_user_op` (`user_id`,`operation_type`),
  KEY `idx_hospital_time` (`hospital_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17391 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of audit_logs

-- ----------------------------
-- Table structure for authorizations
-- ----------------------------
DROP TABLE IF EXISTS `authorizations`;
CREATE TABLE `authorizations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `auth_no` varchar(64) DEFAULT NULL,
  `patient_id` bigint unsigned DEFAULT NULL,
  `auth_target_type` varchar(20) DEFAULT NULL,
  `auth_target_id` bigint unsigned DEFAULT NULL,
  `scope_type` varchar(20) DEFAULT NULL,
  `record_id` bigint unsigned DEFAULT '0',
  `start_time` datetime(3) DEFAULT NULL,
  `end_time` datetime(3) DEFAULT NULL,
  `status` varchar(32) DEFAULT 'ACTIVE',
  `fabric_tx_id` varchar(128) DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  `revoke_tx_id` varchar(128) DEFAULT '',
  `revoke_error` varchar(255) DEFAULT '',
  `operator_id` bigint unsigned DEFAULT '0',
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_authorizations_auth_no` (`auth_no`),
  KEY `idx_patient_target` (`patient_id`,`auth_target_type`,`auth_target_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of authorizations

-- ----------------------------
-- Table structure for blockchain_transactions
-- ----------------------------
DROP TABLE IF EXISTS `blockchain_transactions`;
CREATE TABLE `blockchain_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `business_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tx_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `block_no` bigint unsigned DEFAULT '0',
  `channel_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'medicalchannel',
  `chaincode_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'medical_contract',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'VALID',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_blockchain_transactions_tx_id` (`tx_id`),
  KEY `idx_blockchain_transactions_business_type` (`business_type`),
  KEY `idx_blockchain_transactions_business_id` (`business_id`),
  KEY `idx_blockchain_transactions_block_no` (`block_no`),
  KEY `idx_blockchain_transactions_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=218 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records of blockchain_transactions

-- ----------------------------
-- Table structure for departments
-- ----------------------------
DROP TABLE IF EXISTS `departments`;
CREATE TABLE `departments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `dept_no` varchar(32) DEFAULT NULL,
  `hospital_id` bigint unsigned DEFAULT NULL,
  `name` varchar(64) DEFAULT NULL,
  `description` varchar(255) DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_hospital_id` (`hospital_id`),
  KEY `idx_departments_hospital_id` (`hospital_id`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of departments

-- ----------------------------
-- Table structure for emergency_access_events
-- ----------------------------
DROP TABLE IF EXISTS `emergency_access_events`;
CREATE TABLE `emergency_access_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_no` varchar(64) DEFAULT NULL,
  `doctor_id` bigint unsigned DEFAULT NULL,
  `patient_id` bigint unsigned DEFAULT NULL,
  `record_id` bigint unsigned DEFAULT NULL,
  `source_hospital_id` bigint unsigned DEFAULT NULL,
  `target_hospital_id` bigint unsigned DEFAULT NULL,
  `emergency_reason` varchar(50) DEFAULT NULL,
  `description` text,
  `doctor_confirmed` tinyint DEFAULT '1',
  `patient_feedback` varchar(20) DEFAULT 'PENDING',
  `audit_status` varchar(30) DEFAULT 'PENDING_AUDIT',
  `supervisor_id` bigint unsigned DEFAULT '0',
  `audit_comment` varchar(255) DEFAULT '',
  `fabric_tx_id` varchar(128) DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `patient_comment` varchar(255) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_emergency_access_events_event_no` (`event_no`),
  KEY `idx_doc_pat` (`doctor_id`,`patient_id`),
  KEY `idx_audit_status` (`audit_status`),
  KEY `idx_emergency_access_events_audit_status` (`audit_status`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of emergency_access_events

-- ----------------------------
-- Table structure for hospitals
-- ----------------------------
DROP TABLE IF EXISTS `hospitals`;
CREATE TABLE `hospitals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `hospital_no` varchar(32) DEFAULT NULL,
  `name` varchar(100) DEFAULT NULL,
  `level` varchar(20) DEFAULT '三甲',
  `address` varchar(255) DEFAULT '',
  `status` tinyint DEFAULT '1',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hospitals_hospital_no` (`hospital_no`)
) ENGINE=InnoDB AUTO_INCREMENT=242 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of hospitals

-- ----------------------------
-- Table structure for medical_exam_orders
-- ----------------------------
DROP TABLE IF EXISTS `medical_exam_orders`;
CREATE TABLE `medical_exam_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_id` bigint unsigned DEFAULT NULL,
  `patient_id` bigint unsigned DEFAULT NULL,
  `doctor_id` bigint unsigned DEFAULT NULL,
  `hospital_id` bigint unsigned DEFAULT NULL,
  `department_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `exam_item` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exam_reason` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  `technician_id` bigint unsigned DEFAULT '0',
  `technician_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `exam_result` text COLLATE utf8mb4_unicode_ci,
  `exam_conclusion` text COLLATE utf8mb4_unicode_ci,
  `executed_at` datetime(3) DEFAULT NULL,
  `report_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `report_file_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `ip_fsc_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_medical_exam_orders_order_no` (`order_no`),
  KEY `idx_medical_exam_orders_record_id` (`record_id`),
  KEY `idx_medical_exam_orders_patient_id` (`patient_id`),
  KEY `idx_medical_exam_orders_doctor_id` (`doctor_id`),
  KEY `idx_medical_exam_orders_hospital_id` (`hospital_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records of medical_exam_orders

-- ----------------------------
-- Table structure for medical_files
-- ----------------------------
DROP TABLE IF EXISTS `medical_files`;
CREATE TABLE `medical_files` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `record_id` bigint unsigned DEFAULT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_type` varchar(32) DEFAULT NULL,
  `file_size` bigint unsigned DEFAULT NULL,
  `ipfs_cid` varchar(128) DEFAULT NULL,
  `file_hash` varchar(64) DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `encrypted_dek` varchar(255) DEFAULT '',
  `iv_nonce` varchar(64) DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_ipfs_cid` (`ipfs_cid`),
  KEY `idx_medical_files_record_id` (`record_id`),
  KEY `idx_medical_files_ip_fsc_id` (`ipfs_cid`),
  CONSTRAINT `fk_medical_records_files` FOREIGN KEY (`record_id`) REFERENCES `medical_records` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=312 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of medical_files

-- ----------------------------
-- Table structure for medical_records
-- ----------------------------
DROP TABLE IF EXISTS `medical_records`;
CREATE TABLE `medical_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `record_no` varchar(64) DEFAULT NULL,
  `patient_id` bigint unsigned DEFAULT NULL,
  `doctor_id` bigint unsigned DEFAULT NULL,
  `hospital_id` bigint unsigned DEFAULT NULL,
  `data_type` varchar(32) DEFAULT NULL,
  `onset_time` varchar(50) DEFAULT '',
  `duration` varchar(50) DEFAULT '',
  `symptoms` text,
  `etiology` text,
  `treatment_plan` text,
  `vital_signs` varchar(255) DEFAULT '',
  `diagnosis` text,
  `fabric_tx_id` varchar(128) DEFAULT '',
  `block_height` bigint unsigned DEFAULT '0',
  `created_at` datetime(3) DEFAULT NULL,
  `encounter_type` varchar(32) DEFAULT 'OUTPATIENT',
  `department_name` varchar(64) DEFAULT '综合门诊',
  `status` varchar(32) DEFAULT 'COMPLETED',
  `chief_complaint` text,
  `present_illness` text,
  `initial_diagnosis` text,
  `diagnostic_basis` text,
  `need_exam` tinyint(1) DEFAULT '0',
  `exam_items` varchar(255) DEFAULT '',
  `exam_reason` text,
  `exam_result` text,
  `exam_doctor` varchar(50) DEFAULT '',
  `exam_time` varchar(50) DEFAULT '',
  `sync_status` varchar(32) DEFAULT 'COMPLETED',
  `idempotency_key` varchar(64) DEFAULT NULL,
  `sync_error` text,
  `retry_count` bigint DEFAULT '0',
  `department_id` bigint unsigned DEFAULT '0',
  `title` varchar(128) DEFAULT '',
  `integrity_status` varchar(20) DEFAULT 'VERIFIED',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_medical_records_record_no` (`record_no`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_doctor_hosp` (`doctor_id`,`hospital_id`),
  KEY `idx_medical_records_patient_id` (`patient_id`),
  KEY `idx_medical_records_sync_status` (`sync_status`),
  KEY `idx_medical_records_idempotency_key` (`idempotency_key`)
) ENGINE=InnoDB AUTO_INCREMENT=488 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of medical_records

-- ----------------------------
-- Table structure for risk_records
-- ----------------------------
DROP TABLE IF EXISTS `risk_records`;
CREATE TABLE `risk_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `access_request_id` bigint unsigned DEFAULT '0',
  `access_frequency` bigint DEFAULT '0',
  `time_risk` bigint DEFAULT '0',
  `behavior_risk` bigint DEFAULT '0',
  `total_score` bigint DEFAULT '0',
  `anomaly_flag` tinyint DEFAULT '0',
  `analysis_result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_risk_records_access_request_id` (`access_request_id`),
  KEY `idx_risk_records_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=14199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records of risk_records

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '用户主键',
  `user_no` varchar(64) DEFAULT NULL,
  `username` varchar(50) DEFAULT NULL,
  `password_hash` varchar(255) DEFAULT NULL,
  `real_name` varchar(50) DEFAULT NULL,
  `role` varchar(20) DEFAULT NULL,
  `hospital_id` bigint unsigned DEFAULT '0',
  `department_id` bigint unsigned DEFAULT '0',
  `title` varchar(50) DEFAULT '',
  `phone` varchar(20) DEFAULT '',
  `id_card` varchar(20) DEFAULT '',
  `status` varchar(20) DEFAULT 'NORMAL',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `medical_key` varchar(64) DEFAULT '',
  `medical_key_hash` varchar(128) DEFAULT '',
  `must_change_pwd` tinyint(1) DEFAULT '0',
  `failed_login_count` bigint DEFAULT '0',
  `locked_until` datetime(3) DEFAULT NULL,
  `avatar` longtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_users_user_no` (`user_no`),
  UNIQUE KEY `idx_users_username` (`username`),
  KEY `idx_hosp_dept` (`hospital_id`,`department_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Records of users

SET FOREIGN_KEY_CHECKS = 1;
